using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// Tools
using var httpClient = new HttpClient();
httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
    "ResearchAgent/1.0 (compatible; bot)");

var noteService = new NoteService();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        SearchWebAsync, "SearchWeb",
        "Searches the web for a query and returns a summary of the top results."),
    AIFunctionFactory.Create(
        FetchPageAsync, "FetchPage",
        "Fetches the text content of a specific URL for deeper reading."),
    AIFunctionFactory.Create(
        noteService.TakeNote, "TakeNote",
        "Saves a research note with a title and content."),
    AIFunctionFactory.Create(
        noteService.GetNotes, "GetNotes",
        "Returns all research notes taken so far."),
};

// Agent
var agent = new ChatClientAgent(chatClient)
{
    Name = "ResearchAgent",
    Instructions = """
        You are a research agent. Given a topic, you perform thorough web research
        and produce a well-organized summary. Follow this workflow:

        1. Search the web for the topic using SearchWeb.
        2. Fetch specific pages with FetchPage to gather detailed information.
        3. Use TakeNote to record key findings as you go.
        4. After gathering enough information, use GetNotes to review your notes.
        5. Produce a final, well-structured summary with key findings and sources.

        Be methodical: search, read, note, then summarize.
        """,
    Tools = tools,
};

// Prompt the user
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (v1.0)       ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.Write("\nEnter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

await foreach (var update in agent.InvokeStreamingAsync(history, options))
{
    Console.Write(update.Text);
}

Console.WriteLine("\n\n--- Research Complete ---");

// --- Tool implementations ---

[Description("Searches the web for a query and returns a summary of the top results.")]
async Task<string> SearchWebAsync(
    [Description("The search query")] string query)
{
    Console.ForegroundColor = ConsoleColor.DarkCyan;
    Console.WriteLine($"  🔍 Searching: {query}");
    Console.ResetColor();

    try
    {
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
        var html = await httpClient.GetStringAsync(url);
        return ParseSearchResults(html);
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

[Description("Fetches the text content of a specific URL for deeper reading.")]
async Task<string> FetchPageAsync(
    [Description("The URL to fetch")] string url)
{
    Console.ForegroundColor = ConsoleColor.DarkCyan;
    Console.WriteLine($"  🌐 Fetching: {url}");
    Console.ResetColor();

    try
    {
        var html = await httpClient.GetStringAsync(url);
        var text = StripHtml(html);

        // Limit to ~4000 chars to stay within context limits
        return text.Length > 4000
            ? text[..4000] + "\n... [truncated]"
            : text;
    }
    catch (Exception ex)
    {
        return $"Fetch failed: {ex.Message}";
    }
}

static string ParseSearchResults(string html)
{
    var sb = new StringBuilder();
    // Extract result snippets from DuckDuckGo Lite HTML
    var snippetMatches = Regex.Matches(html, @"<td[^>]*class=""result-snippet""[^>]*>(.*?)</td>",
        RegexOptions.Singleline | RegexOptions.IgnoreCase);
    var linkMatches = Regex.Matches(html, @"<a[^>]*rel=""nofollow""[^>]*href=""([^""]+)""[^>]*class=""result-link""[^>]*>(.*?)</a>",
        RegexOptions.Singleline | RegexOptions.IgnoreCase);

    var count = Math.Min(linkMatches.Count, 5);

    if (count == 0)
    {
        return "No results found. Try a different search query.";
    }

    for (var i = 0; i < count; i++)
    {
        var title = StripHtml(linkMatches[i].Groups[2].Value).Trim();
        var link = linkMatches[i].Groups[1].Value.Trim();
        var snippet = i < snippetMatches.Count
            ? StripHtml(snippetMatches[i].Groups[1].Value).Trim()
            : "";

        sb.AppendLine($"{i + 1}. {title}");
        sb.AppendLine($"   URL: {link}");
        if (!string.IsNullOrEmpty(snippet))
            sb.AppendLine($"   {snippet}");
        sb.AppendLine();
    }

    return sb.ToString();
}

static string StripHtml(string html)
{
    // Remove script and style blocks
    var cleaned = Regex.Replace(html, @"<(script|style)[^>]*>.*?</\1>", "",
        RegexOptions.Singleline | RegexOptions.IgnoreCase);
    // Replace block-level tags with newlines
    cleaned = Regex.Replace(cleaned, @"<(br|p|div|h[1-6]|li|tr)[^>]*>", "\n",
        RegexOptions.IgnoreCase);
    // Remove remaining tags
    cleaned = Regex.Replace(cleaned, @"<[^>]+>", "");
    // Decode entities
    cleaned = WebUtility.HtmlDecode(cleaned);
    // Collapse whitespace
    cleaned = Regex.Replace(cleaned, @"[ \t]+", " ");
    cleaned = Regex.Replace(cleaned, @"\n{3,}", "\n\n");
    return cleaned.Trim();
}

// --- Note service ---

sealed class NoteService
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Saves a research note with a title and content.")]
    public string TakeNote(
        [Description("Short title for the note")] string title,
        [Description("The note content")] string content)
    {
        _notes.Add((title, content));

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved: {title}");
        Console.ResetColor();

        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Returns all research notes taken so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"--- Note #{i + 1}: {_notes[i].Title} ---");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

