 [Description("Searches the web for a query and returns a summary of the top results.")]
 async Task<string> SearchWebAsync(
     [Description("The search query")] string query)
 {
     Console.ForegroundColor = ConsoleColor.DarkCyan;
     Console.WriteLine($"  🔍 Searching: {query}");
     Console.ResetColor();

     try
     {
         var encoded = WebUtility.UrlEncode(query);
         var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
         var html = await httpClient.GetStringAsync(url);
         return ParseSearchResults(html);
     }
     catch (Exception ex)
     {
         return $"Search failed: {ex.Message}";
     }
 }

 [Description("Fetches the text content of a specific URL for deeper reading.")]
 async Task<string> FetchPageAsync(
     [Description("The URL to fetch")] string url)
 {
     Console.ForegroundColor = ConsoleColor.DarkCyan;
     Console.WriteLine($"  🌐 Fetching: {url}");
     Console.ResetColor();

     try
     {
         var html = await httpClient.GetStringAsync(url);
         var text = StripHtml(html);

         return text.Length > 4000
             ? text[..4000] + "\n... [truncated]"
             : text;
     }
     catch (Exception ex)
     {
         return $"Fetch failed: {ex.Message}";
     }
 }

 static string ParseSearchResults(string html)
 {
     var sb = new StringBuilder();
     var snippetMatches = Regex.Matches(html, @"<td[^>]*class=""result-snippet""[^>]*>(.*?)</td>",
         RegexOptions.Singleline | RegexOptions.IgnoreCase);
     var linkMatches = Regex.Matches(html, @"<a[^>]*rel=""nofollow""[^>]*href=""([^""]+)""[^>]*class=""result-link""[^>]*>(.*?)</a>",
         RegexOptions.Singleline | RegexOptions.IgnoreCase);

     var count = Math.Min(linkMatches.Count, 5);

     if (count == 0)
         return "No results found. Try a different search query.";

     for (var i = 0; i < count; i++)
     {
         var title = StripHtml(linkMatches[i].Groups[2].Value).Trim();
         var link = linkMatches[i].Groups[1].Value.Trim();
         var snippet = i < snippetMatches.Count
             ? StripHtml(snippetMatches[i].Groups[1].Value).Trim()
             : "";

         sb.AppendLine($"{i + 1}. {title}");
         sb.AppendLine($"   URL: {link}");
         if (!string.IsNullOrEmpty(snippet))
             sb.AppendLine($"   {snippet}");
         sb.AppendLine();
     }

     return sb.ToString();
 }

 static string StripHtml(string html)
 {
     var cleaned = Regex.Replace(html, @"<(script|style)[^>]*>.*?</\1>", "",
         RegexOptions.Singleline | RegexOptions.IgnoreCase);
     cleaned = Regex.Replace(cleaned, @"<(br|p|div|h[1-6]|li|tr)[^>]*>", "\n",
         RegexOptions.IgnoreCase);
     cleaned = Regex.Replace(cleaned, @"<[^>]+>", "");
     cleaned = WebUtility.HtmlDecode(cleaned);
     cleaned = Regex.Replace(cleaned, @"[ \t]+", " ");
     cleaned = Regex.Replace(cleaned, @"\n{3,}", "\n\n");
     return cleaned.Trim();
 }

